namespace hanmo::resident {namespace {
using V=BoundaryValue;
bool id(const StableId& s){return !s.empty()&&s.size()<=256;}
bool order(const FieldOrder& f,const std::set<StableId>& keys){return f.empty()||(f.size()==keys.size()&&std::set<StableId>(f.begin(),f.end())==keys);}
Status shape(const ChildCareReliefAgreement& p){return p.kind=="family_care_relief_accepted"&&p.source.terms.food_per_period>=1&&p.source.terms.food_per_period<=10000&&p.source.terms.prepaid_periods>=1&&p.source.terms.prepaid_periods<=360&&p.reserved_food==p.source.terms.food_per_period*p.source.terms.prepaid_periods&&order(p.field_order,{"kind","source","reserved_food"})?common_success():common_failure("InvalidChildCareReliefAgreement");}
ChildCareReliefAgreement read_ChildCareReliefAgreement(const V& v){using namespace boundary;fields(v,{"kind","source","reserved_food"},{},"care_relief");ChildCareReliefAgreement p;p.kind=get_string(v,"kind","");auto from=decode_child_care_relief_source(field(v,"source",""));if(!from.ok){DecodeFailure error{"InvalidChildCareReliefSource","source"};error.error=from.error;throw error;}p.source=std::move(from.value);p.reserved_food=get_int(v,"reserved_food","");p.field_order=boundary::order(v);auto valid=shape(p);if(!valid.ok)fail(valid.error.original.code,"");return p;}
V encode(const ChildCareReliefAgreement& p){return family_projection::encode([&](auto& w){return emit_child_care_relief_agreement_fields(w,p);});}
Status visit(CodecVisitor& c,ChildCareReliefAgreement& p){c.field("kind",p.kind);c.object("source",[&](CodecVisitor& at){return visit_child_care_relief_source(at,p.source);});c.field("reserved_food",p.reserved_food);common_checkpoint::strings(c,"field_order",p.field_order);if(!c.status().ok)return c.status();auto valid=shape(p);return valid.ok?c.status():c.reject(valid.error.original.code);}
Status shape(const ChildCareReliefStart& p){return p.kind=="family_care_relief_started"&&id(p.accepted_id)&&id(p.action_id)&&id(p.provider_actor_id)&&id(p.child_actor_id)&&id(p.place_id)&&p.tick>=0&&p.tick<=2147483647&&p.revision>=0&&p.duration>=1&&p.duration<=720&&p.tick<=2147483647-p.duration&&p.period_index>=1&&p.period_index<=360&&p.provider_actor_id!=p.child_actor_id&&order(p.field_order,{"kind","accepted_id","action_id","provider_actor_id","child_actor_id","place_id","tick","revision","duration","period_index"})?common_success():common_failure("InvalidChildCareReliefStart");}
ChildCareReliefStart read_ChildCareReliefStart(const V& v){using namespace boundary;fields(v,{"kind","accepted_id","action_id","provider_actor_id","child_actor_id","place_id","tick","revision","duration","period_index"},{},"care_relief");ChildCareReliefStart p;p.kind=get_string(v,"kind","");p.accepted_id=get_string(v,"accepted_id","");p.action_id=get_string(v,"action_id","");p.provider_actor_id=get_string(v,"provider_actor_id","");p.child_actor_id=get_string(v,"child_actor_id","");p.place_id=get_string(v,"place_id","");p.tick=get_int(v,"tick","");p.revision=get_int(v,"revision","");p.duration=get_int(v,"duration","");p.period_index=get_int(v,"period_index","");p.field_order=boundary::order(v);auto valid=shape(p);if(!valid.ok)fail(valid.error.original.code,"");return p;}
V encode(const ChildCareReliefStart& p){return family_projection::encode([&](auto& w){return emit_child_care_relief_start_fields(w,p);});}
Status visit(CodecVisitor& c,ChildCareReliefStart& p){c.field("kind",p.kind);c.field("accepted_id",p.accepted_id);c.field("action_id",p.action_id);c.field("provider_actor_id",p.provider_actor_id);c.field("child_actor_id",p.child_actor_id);c.field("place_id",p.place_id);c.field("tick",p.tick);c.field("revision",p.revision);c.field("duration",p.duration);c.field("period_index",p.period_index);common_checkpoint::strings(c,"field_order",p.field_order);if(!c.status().ok)return c.status();auto valid=shape(p);return valid.ok?c.status():c.reject(valid.error.original.code);}
Status shape(const ChildCareReliefReceipt& p){return p.kind=="family_care_relief_provided"&&id(p.accepted_id)&&id(p.action_id)&&id(p.provider_actor_id)&&id(p.child_actor_id)&&id(p.place_id)&&id(p.outcome)&&p.tick>=0&&p.tick<=2147483647&&p.revision>=0&&p.started_tick>=0&&p.started_tick<=p.tick&&p.period_index>=1&&p.period_index<=360&&p.provider_actor_id!=p.child_actor_id&&((p.outcome=="completed"&&p.food_consumed>=1&&p.food_consumed<=10000&&p.code.empty()&&p.interruption_fact_id.empty())||(p.outcome=="cancelled"&&p.food_consumed==0&&((p.code=="CareReliefProviderStopped"&&p.interruption_fact_id.empty())||((p.code=="CareReliefProviderDied"||p.code=="CareReliefChildDied")&&id(p.interruption_fact_id)))))&&order(p.field_order,{"kind","accepted_id","action_id","provider_actor_id","child_actor_id","place_id","outcome","code","interruption_fact_id","started_tick","tick","revision","period_index","food_consumed"})?common_success():common_failure("InvalidChildCareReliefReceipt");}
ChildCareReliefReceipt read_ChildCareReliefReceipt(const V& v){using namespace boundary;fields(v,{"kind","accepted_id","action_id","provider_actor_id","child_actor_id","place_id","outcome","code","interruption_fact_id","started_tick","tick","revision","period_index","food_consumed"},{},"care_relief");ChildCareReliefReceipt p;p.kind=get_string(v,"kind","");p.accepted_id=get_string(v,"accepted_id","");p.action_id=get_string(v,"action_id","");p.provider_actor_id=get_string(v,"provider_actor_id","");p.child_actor_id=get_string(v,"child_actor_id","");p.place_id=get_string(v,"place_id","");p.outcome=get_string(v,"outcome","");p.code=get_string(v,"code","");p.interruption_fact_id=get_string(v,"interruption_fact_id","");p.started_tick=get_int(v,"started_tick","");p.tick=get_int(v,"tick","");p.revision=get_int(v,"revision","");p.period_index=get_int(v,"period_index","");p.food_consumed=get_int(v,"food_consumed","");p.field_order=boundary::order(v);auto valid=shape(p);if(!valid.ok)fail(valid.error.original.code,"");return p;}
V encode(const ChildCareReliefReceipt& p){return family_projection::encode([&](auto& w){return emit_child_care_relief_receipt_fields(w,p);});}
Status visit(CodecVisitor& c,ChildCareReliefReceipt& p){c.field("kind",p.kind);c.field("accepted_id",p.accepted_id);c.field("action_id",p.action_id);c.field("provider_actor_id",p.provider_actor_id);c.field("child_actor_id",p.child_actor_id);c.field("place_id",p.place_id);c.field("outcome",p.outcome);c.field("code",p.code);c.field("interruption_fact_id",p.interruption_fact_id);c.field("started_tick",p.started_tick);c.field("tick",p.tick);c.field("revision",p.revision);c.field("period_index",p.period_index);c.field("food_consumed",p.food_consumed);common_checkpoint::strings(c,"field_order",p.field_order);if(!c.status().ok)return c.status();auto valid=shape(p);return valid.ok?c.status():c.reject(valid.error.original.code);}
Status shape(const ChildCareReliefClosure& p){return p.kind=="family_care_relief_closed"&&id(p.accepted_id)&&id(p.actor_id)&&id(p.reason)&&p.tick>=0&&p.tick<=2147483647&&p.revision>=0&&p.released_food>=0&&p.released_food<=3600000&&((p.reason=="finite_care_completed"&&p.released_food==0&&id(p.source_fact_id))||((p.reason=="provider_withdrew"||p.reason=="parent_withdrew")&&p.source_fact_id.empty())||((p.reason=="provider_died"||p.reason=="child_died")&&id(p.source_fact_id)))&&order(p.field_order,{"kind","accepted_id","actor_id","reason","source_fact_id","tick","revision","released_food"})?common_success():common_failure("InvalidChildCareReliefClosure");}
ChildCareReliefClosure read_ChildCareReliefClosure(const V& v){using namespace boundary;fields(v,{"kind","accepted_id","actor_id","reason","source_fact_id","tick","revision","released_food"},{},"care_relief");ChildCareReliefClosure p;p.kind=get_string(v,"kind","");p.accepted_id=get_string(v,"accepted_id","");p.actor_id=get_string(v,"actor_id","");p.reason=get_string(v,"reason","");p.source_fact_id=get_string(v,"source_fact_id","");p.tick=get_int(v,"tick","");p.revision=get_int(v,"revision","");p.released_food=get_int(v,"released_food","");p.field_order=boundary::order(v);auto valid=shape(p);if(!valid.ok)fail(valid.error.original.code,"");return p;}
V encode(const ChildCareReliefClosure& p){return family_projection::encode([&](auto& w){return emit_child_care_relief_closure_fields(w,p);});}
Status visit(CodecVisitor& c,ChildCareReliefClosure& p){c.field("kind",p.kind);c.field("accepted_id",p.accepted_id);c.field("actor_id",p.actor_id);c.field("reason",p.reason);c.field("source_fact_id",p.source_fact_id);c.field("tick",p.tick);c.field("revision",p.revision);c.field("released_food",p.released_food);common_checkpoint::strings(c,"field_order",p.field_order);if(!c.status().ok)return c.status();auto valid=shape(p);return valid.ok?c.status():c.reject(valid.error.original.code);}
}
Outcome<ChildCareReliefState> decode_child_care_relief(const V& v){try{using namespace boundary;auto unique=validate_succession_json_unique(v);if(!unique.ok)return {false,{},unique.error};fields(v,{"agreements","starts","care","closures"},{},"child_care_relief");ChildCareReliefState s;for(const auto& row:object(field(v,"agreements",""),"agreements")){if(!id(row.first)||!s.agreements.insert(row.first,read_ChildCareReliefAgreement(row.second)))fail("InvalidChildCareReliefTableKey",row.first);}for(const auto& row:object(field(v,"starts",""),"starts")){if(!id(row.first)||!s.starts.insert(row.first,read_ChildCareReliefStart(row.second)))fail("InvalidChildCareReliefTableKey",row.first);}for(const auto& row:object(field(v,"care",""),"care")){if(!id(row.first)||!s.care.insert(row.first,read_ChildCareReliefReceipt(row.second)))fail("InvalidChildCareReliefTableKey",row.first);}for(const auto& row:object(field(v,"closures",""),"closures")){if(!id(row.first)||!s.closures.insert(row.first,read_ChildCareReliefClosure(row.second)))fail("InvalidChildCareReliefTableKey",row.first);}s.field_order=boundary::order(v);return {true,std::move(s),{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
Status emit_child_care_relief_agreement_fields(ProjectionWriter& w,const ChildCareReliefAgreement& p){auto valid=shape(p);if(!valid.ok)return w.reject(valid.error.original.code,"");w.field("kind",p.kind);w.object("source",[&](auto& out){return emit_child_care_relief_source_fields(out,p.source);});w.field("reserved_food",p.reserved_food);return w.order_fields(p.field_order);}
Status emit_child_care_relief_start_fields(ProjectionWriter& w,const ChildCareReliefStart& p){auto valid=shape(p);if(!valid.ok)return w.reject(valid.error.original.code,"");w.field("kind",p.kind);w.field("accepted_id",p.accepted_id);w.field("action_id",p.action_id);w.field("provider_actor_id",p.provider_actor_id);w.field("child_actor_id",p.child_actor_id);w.field("place_id",p.place_id);w.field("tick",p.tick);w.field("revision",p.revision);w.field("duration",p.duration);w.field("period_index",p.period_index);return w.order_fields(p.field_order);}
Status emit_child_care_relief_receipt_fields(ProjectionWriter& w,const ChildCareReliefReceipt& p){auto valid=shape(p);if(!valid.ok)return w.reject(valid.error.original.code,"");w.field("kind",p.kind);w.field("accepted_id",p.accepted_id);w.field("action_id",p.action_id);w.field("provider_actor_id",p.provider_actor_id);w.field("child_actor_id",p.child_actor_id);w.field("place_id",p.place_id);w.field("outcome",p.outcome);w.field("code",p.code);w.field("interruption_fact_id",p.interruption_fact_id);w.field("started_tick",p.started_tick);w.field("tick",p.tick);w.field("revision",p.revision);w.field("period_index",p.period_index);w.field("food_consumed",p.food_consumed);return w.order_fields(p.field_order);}
Status emit_child_care_relief_closure_fields(ProjectionWriter& w,const ChildCareReliefClosure& p){auto valid=shape(p);if(!valid.ok)return w.reject(valid.error.original.code,"");w.field("kind",p.kind);w.field("accepted_id",p.accepted_id);w.field("actor_id",p.actor_id);w.field("reason",p.reason);w.field("source_fact_id",p.source_fact_id);w.field("tick",p.tick);w.field("revision",p.revision);w.field("released_food",p.released_food);return w.order_fields(p.field_order);}
Status emit_child_care_relief_fields(ProjectionWriter& w,const ChildCareReliefState& s){if(!order(s.field_order,{"agreements","starts","care","closures"}))return w.reject("BoundaryFieldOrderMismatch","");auto table=[&](std::string_view key,const auto& rows,auto emit){return w.object(key,[&](auto& out){for(const auto& row:rows.rows()){if(!id(row.first))return out.reject("InvalidChildCareReliefTableKey",row.first);out.object(row.first,[&](auto& value){return emit(value,row.second);});if(!out.status().ok)return out.status();}return out.status();});};table("agreements",s.agreements,emit_child_care_relief_agreement_fields);table("starts",s.starts,emit_child_care_relief_start_fields);table("care",s.care,emit_child_care_relief_receipt_fields);table("closures",s.closures,emit_child_care_relief_closure_fields);return w.order_fields(s.field_order);}
BoundaryValue encode_child_care_relief(const ChildCareReliefState& s){return family_projection::encode([&](auto& w){return emit_child_care_relief_fields(w,s);});}
Status visit_child_care_relief_checkpoint(CodecVisitor& c,ChildCareReliefState& s){common_checkpoint::table(c,"agreements",s.agreements,[](CodecVisitor& at,ChildCareReliefAgreement& p){return visit(at,p);});common_checkpoint::table(c,"starts",s.starts,[](CodecVisitor& at,ChildCareReliefStart& p){return visit(at,p);});common_checkpoint::table(c,"care",s.care,[](CodecVisitor& at,ChildCareReliefReceipt& p){return visit(at,p);});common_checkpoint::table(c,"closures",s.closures,[](CodecVisitor& at,ChildCareReliefClosure& p){return visit(at,p);});common_checkpoint::strings(c,"field_order",s.field_order);if(!c.status().ok)return c.status();if(!order(s.field_order,{"agreements","starts","care","closures"}))return c.reject("BoundaryFieldOrderMismatch");for(const auto& row:s.agreements.rows())if(!id(row.first))return c.reject("InvalidChildCareReliefTableKey");for(const auto& row:s.starts.rows())if(!id(row.first))return c.reject("InvalidChildCareReliefTableKey");for(const auto& row:s.care.rows())if(!id(row.first))return c.reject("InvalidChildCareReliefTableKey");for(const auto& row:s.closures.rows())if(!id(row.first))return c.reject("InvalidChildCareReliefTableKey");return c.status();}
}
